// Sanitize and classify an n8n execution error before it is logged or alerted.
// Runs once per failed execution (input comes from the Error Trigger).
const err = $input.first().json;

const SENSITIVE_KEYS = /(api[_-]?key|authorization|bearer|password|passwd|secret|token|cookie|session|signature)/i;
const PATTERNS = [
  [/Bearer\s+[A-Za-z0-9._\-]+/g, 'Bearer [REDACTED]'],
  [/sk-[A-Za-z0-9_\-]{12,}/g, '[REDACTED_KEY]'],
  [/[A-Za-z0-9._%+\-]+@[A-Za-z0-9.\-]+\.[A-Za-z]{2,}/g, '[EMAIL]'],
  [/\+?\d[\d\s\-()]{8,}\d/g, '[PHONE]'],
];

function scrubString(s) {
  return PATTERNS.reduce((out, [re, rep]) => out.replace(re, rep), s);
}

function sanitize(value, depth = 0) {
  if (depth > 8) return '[TRUNCATED]';
  if (typeof value === 'string') return scrubString(value).slice(0, 2000);
  if (Array.isArray(value)) return value.slice(0, 50).map(v => sanitize(v, depth + 1));
  if (value && typeof value === 'object') {
    const out = {};
    for (const [k, v] of Object.entries(value)) {
      out[k] = SENSITIVE_KEYS.test(k) ? '[REDACTED]' : sanitize(v, depth + 1);
    }
    return out;
  }
  return value;
}

const message = scrubString(String(err.execution?.error?.message || 'Unknown error'));
const node = err.execution?.lastNodeExecuted || 'unknown';

// Severity: customer-facing or data-loss risks page someone; transient issues are logged only.
const HIGH = /(webhook|whatsapp|messenger|telegram|send|calendar|book|payment|unauthori[sz]ed|401|403)/i;
const LOW = /(rate.?limit|429|timeout|ETIMEDOUT|ECONNRESET|socket hang up)/i;
const haystack = `${node} ${message}`;
const severity = HIGH.test(haystack) ? 'high' : LOW.test(haystack) ? 'low' : 'medium';

return [{
  json: {
    occurred_at: new Date().toISOString(),
    severity,
    workflow_id: err.workflow?.id || null,
    workflow_name: err.workflow?.name || 'unknown',
    failed_node: node,
    error_message: message,
    execution_id: err.execution?.id || null,
    execution_url: err.execution?.url || null,
    retry_of: err.execution?.retryOf || null,
    context: sanitize(err.execution?.error || {}),
  },
}];

